INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ライラエル", -470.0, 0.0, "2023/09/22 14:59:59", 2, 2, "ショップへようこそ\nキャラバンコインはこちら\nで買い物に使えますよ", 2002, 126501, "2023/06/30 12:00:00", 1, 1, 10003, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ライラエル", -470.0, 0.0, "2023/09/22 14:59:59", 1, 1, "こちらのショップで\n買い物をして、素敵な\n旅を楽しんでくださいね", 2002, 126501, "2023/06/30 12:00:00", 2, 1, 10004, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("リンド", -470.0, 0.0, "2023/12/22 14:59:59", 2, 2, "いらっしゃいませ\nキャラバンコインを使って\nお買い物ができますよ", 2002, 127702, "2023/09/15 15:00:00", 1, 2, 10005, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("リンド", -470.0, 0.0, "2023/12/22 14:59:59", 2, 2, "ショップの掃除は完璧です\n姫さま直営のお店として\n当然のことですから", 2002, 127702, "2023/09/15 15:00:00", 2, 2, 10006, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ヴルム", -470.0, 0.0, "2023/12/22 14:59:59", 1, 1, "ショップへようこそ\nキャラバンコインと品物を\n交換できるんで、よければ", 2002, 127802, "2023/09/15 15:00:00", 1, 2, 10007, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ヴルム", -470.0, 0.0, "2023/12/22 14:59:59", 1, 2, "なんで店番なんか…\nま、やりますけど\n好きな品物をどうぞ", 2002, 127802, "2023/09/15 15:00:00", 2, 2, 10008, 6.5);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("アネモネ", -470.0, 0.0, "2024/03/22 14:59:59", 1, 2, "──いらっしゃいませ\n買い物しても、いいですよ\nキャラバンコインがあれば", 2002, 129602, "2023/12/15 15:00:00", 1, 3, 10009, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("アネモネ", -470.0, 0.0, "2024/03/22 14:59:59", 1, 2, "──もっと笑顔がほしい？\nいくらコインを積まれても\n売れない物はありますから", 2002, 129602, "2023/12/15 15:00:00", 2, 3, 10010, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ネフィ=ネラ", -470.0, 0.0, "2024/03/22 14:59:59", 1, 1, "ようこそおいでなんし\nキャラバンコインをこちら\nで交換して進ぜんしょう", 2002, 129701, "2023/12/15 15:00:00", 1, 3, 10011, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ネフィ=ネラ", -470.0, 0.0, "2024/03/22 14:59:59", 1, 2, "ところで、お前さまは\nいくらで贖えるのか喃？\n──フフ、冗談でありんす", 2002, 129701, "2023/12/15 15:00:00", 2, 3, 10012, 6.2);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("カノン", -470.0, 0.0, "2024/06/22 14:59:59", 5, 3, "い、いらっしゃいませっ！\n…くっ…このあたくし様が\n店番なんて…屈辱ですわっ", 2002, 130301, "2024/03/15 15:00:00", 1, 4, 10013, 3.1);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("カノン", -470.0, 0.0, "2024/06/22 14:59:59", 2, 3, "あら、あたくしをご所望？\nお生憎様、そんな小銭では\n…買えちゃうんですの！？", 2002, 130301, "2024/03/15 15:00:00", 2, 4, 10014, 6.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ナーナ", -470.0, 0.0, "2024/06/22 14:59:59", 2, 2, "いらっしゃいませ～♪\nきゃらばんこいん？を\n交換できるんだってー", 2002, 130401, "2024/03/15 15:00:00", 1, 4, 10015, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ナーナ", -470.0, 0.0, "2024/06/22 14:59:59", 1, 2, "甘いのくれたら、\nお礼にナーナの拾った\n松ぼっくりあげちゃうよ！", 2002, 130401, "2024/03/15 15:00:00", 2, 4, 10016, 3.35);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ホウオウ", -470.0, 0.0, "2024/09/22 14:59:59", 1, 1, "ショップへようこそ\nこの鳳凰が、皆さんに\n祝福を差し上げましょう", 2002, 130502, "2024/06/15 15:00:00", 1, 5, 10017, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ホウオウ", -470.0, 0.0, "2024/09/22 14:59:59", 1, 2, "ほーちゃんと呼ぶ権利は\n売っていませんよ？\n騎士さんへの、特別です！", 2002, 130502, "2024/06/15 15:00:00", 2, 5, 10018, 3.18);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ホウオウ", -470.0, 0.0, "2024/09/22 14:59:59", 4, 4, "うﾞぇぇえんっ！まﾞだごの\n格好になっぢゃいまじだ！\n寄付をお願いじまず～っ！", 2002, 130503, "2024/06/15 15:00:00", 3, 5, 10019, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ネア", -470.0, 0.0, "2024/09/22 14:59:59", 2, 1, "おっすー♪\nなんでも交換してけー\nカリザきゅん以外で", 2002, 123301, "2024/06/15 15:00:00", 1, 5, 10020, 4.9);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ネア", -470.0, 0.0, "2024/09/22 14:59:59", 2, 1, "ところで、騎士きゅんは\nおいくら万ルピ？\nジョーダンぬ・き・で♡", 2002, 123301, "2024/06/15 15:00:00", 2, 5, 10021, 4.8);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("カリザ", -470.0, 0.0, "2024/12/22 14:59:59", 1, 3, "ケッ、なんでオレ様が店番\nなんざ…って来んなキイロ\nオレは売りモンじゃねー！", 2002, 133301, "2024/09/15 15:00:00", 1, 6, 10022, 4.922);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("カリザ", -470.0, 0.0, "2024/12/22 14:59:59", 5, 3, "い、言わなきゃダメか？\n「…いらっしゃいませ…」\nクソッ、笑うんじゃねー！", 2002, 133301, "2024/09/15 15:00:00", 2, 6, 10023, 9.638);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ミーア", -470.0, 0.0, "2024/12/22 14:59:59", 2, 1, "ショップへようこそ～\nネラさまの腹心…的な私が\n店番させていただきま～す", 2002, 133401, "2024/09/15 15:00:00", 1, 6, 10024, 2.88);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ミーア", -470.0, 0.0, "2024/12/22 14:59:59", 1, 5, "私の抜け殻とか、\n需要ありますかね～…\nって冗談ですよ、冗談！", 2002, 133401, "2024/09/15 15:00:00", 2, 6, 10025, 4.818);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("グレイス", -470.0, 0.0, "2025/03/22 14:59:59", 1, 2, "へい、らっしゃい\nさ、騎士氏。冥土の土産は\nなにがいいですか？", 2002, 133002, "2024/12/15 15:00:00", 1, 7, 10026, 1.78);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("グレイス", -470.0, 0.0, "2025/03/22 14:59:59", 7, 1, "商品をお買い上げ毎に\nグレイスちゃんポイントを\n差し上げます。嘘ですが", 2002, 133002, "2024/12/15 15:00:00", 2, 7, 10027, 6.15);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ヴァイオレット", -470.0, 0.0, "2025/03/22 14:59:59", 2, 6, "ようこそいらっしゃいませ\n…接客とは、このような\n振舞で宜しいでしょうか？", 2002, 133102, "2024/12/15 15:00:00", 1, 7, 10028, 4.28);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ヴァイオレット", -470.0, 0.0, "2025/03/22 14:59:59", 1, 1, "じめじめした商品は\nございませんので\n安心してお買い求め下さい", 2002, 133102, "2024/12/15 15:00:00", 2, 7, 10029, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ルルィ", -470.0, 0.0, "2025/06/23 14:59:59", 1, 2, "いらっしゃいましぇでしゅ\n何をお求めでしゅか？\nたこ焼きもありましゅよ！", 2002, 136902, "2025/03/15 15:00:00", 1, 8, 10030, 5.53);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ルルィ", -470.0, 0.0, "2025/06/23 14:59:59", 7, 9, "そのコイン…ピカピカで、\n集めたくなっちゃいましゅ\nタコ釣られされちゃう～…", 2002, 136902, "2025/03/15 15:00:00", 2, 8, 10031, 6.05);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("デュラン", -470.0, 0.0, "2025/06/23 14:59:59", 1, 2, "姫のご友人ならば\n礼儀を尽くすのが爺の務め\nさ、望みの物を言いたまえ", 2002, 137001, "2025/03/15 15:00:00", 1, 8, 10032, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("デュラン", -470.0, 0.0, "2025/06/23 14:59:59", 1, 2, "キャラバンコインではなく\n首で支払って貰えんかのぅ\n…冗談であるぞ？", 2002, 137001, "2025/03/15 15:00:00", 2, 8, 10033, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("サツキ", -470.0, 0.0, "2025/09/23 14:59:59", 2, 2, "おう\n好きなもん持ってきな", 2002, 135902, "2025/06/16 15:00:00", 1, 9, 10034, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("サツキ", -470.0, 0.0, "2025/09/23 14:59:59", 6, 1, "宵越しの銭を持つような\n野暮いマネぁしくさんな\nツキが落ちてもしらねぇぜ", 2002, 135902, "2025/06/16 15:00:00", 2, 9, 10035, 4.935);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ユキノ", -470.0, 0.0, "2025/09/23 14:59:59", 5, 2, "ら、ら、らっしゃっせ…\nなんかほしいもん、ある？\nか、かき氷とか、ど…？", 2002, 135802, "2025/06/16 15:00:00", 1, 9, 10036, 7.441);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ユキノ", -470.0, 0.0, "2025/09/23 14:59:59", 7, 7, "そ、そんな見ねぇで…\nあては、売りもんじゃ\nねぇよ…？", 2002, 135802, "2025/06/16 15:00:00", 2, 9, 10037, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("クルル", -470.0, 0.0, "2025/12/22 14:59:59", 2, 2, "クルルをお求めですかっ？\nそれならお礼に、こちらの\n宝石もどうぞですよ～♪", 2002, 130901, "2025/09/16 15:00:00", 1, 10, 10038, 2.295);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("クルル", -470.0, 0.0, "2025/12/22 14:59:59", 6, 1, "はっ！　ヒーローさんから\nお代なんて頂けないです！\nどうぞどうぞ…え、ダメ？", 2002, 130901, "2025/09/16 15:00:00", 2, 10, 10039, 6.281);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ヴォルガーノ", -470.0, 0.0, "2025/12/22 14:59:59", 1, 2, "よぅ！　今日の俺さまは\n門番じゃなく、店番だぜ\nメモピ～スフィア～てな！", 2002, 137701, "2025/09/16 15:00:00", 1, 10, 10040, 5.549);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ヴォルガーノ", -470.0, 0.0, "2025/12/22 14:59:59", 6, 3, "…リマさんのブロマイド？\n買い取るに決まってらぁ！\nなんでも持ってけ泥棒っ！", 2002, 137701, "2025/09/16 15:00:00", 2, 10, 10041, 2.64);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ライラエル", -470.0, 0.0, "2026/03/23 11:59:59", 4, 7, "こ、この格好は…ヴルムが\n集客効果があると言って…\n…本当でしょうか？", 2002, 132801, "2025/12/15 15:00:00", 1, 11, 10042, 7.642);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ライラエル", -470.0, 0.0, "2026/03/23 11:59:59", 1, 1, "この我に店番させるとは…\n全て買わねば許さぬぞ\n我が国庫に貢献するが良い", 2002, 132802, "2025/12/15 15:00:00", 2, 11, 10043, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("クローチェ", -470.0, 0.0, "2026/03/23 11:59:59", 1, 1, "アナライズっ！\n本日のオススメ商品は～…\nこちらですっ♪", 2002, 134502, "2025/12/15 15:00:00", 1, 11, 10044, 0.0);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("クローチェ", -470.0, 0.0, "2026/03/23 11:59:59", 1, 2, "ギガンティックローチェ、\nおひとついかがですかっ？\n格納庫用意して下さいねっ", 2002, 134501, "2025/12/15 15:00:00", 2, 11, 10045, 3.72);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ネフィ＝ネラ", -470.0, 0.0, "2026/06/22 11:59:59", 1, 2, "番頭も、飯事の如き営み\nなれば。愛らしき稚児らで\n千客万来といきませぬか喃", 2002, 138201, "2026/03/16 12:00:00", 1, 12, 10046, 4.991);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("ネフィ＝ネラ", -470.0, 0.0, "2026/06/22 11:59:59", 4, 1, "国を営むに金子は必須也…\nどうか御恵みくだしゃんせ\n誠心を以て報恩致しまする", 2002, 138201, "2026/03/16 12:00:00", 2, 12, 10047, 3.877);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("アラクネ", -470.0, 0.0, "2026/06/22 11:59:59", 6, 4, "あぅっ…！　天井が低くて\n頭をぶつけてしまって…\nわたしが、大きいだけ…？", 2002, 136001, "2026/03/16 12:00:00", 1, 12, 10048, 1.71);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("アラクネ", -470.0, 0.0, "2026/06/22 11:59:59", 2, 5, "いらっしゃいませ騎士さま\nくつろいでいって下さいね\nもし叶うなら…永遠に…", 2002, 136001, "2026/03/16 12:00:00", 2, 12, 10049, 5.32);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("アネモネ", -470.0, 0.0, "2026/09/22 11:59:59", 4, 9, "水着で、店番とか──\n本当、意味がわかりません\n海の家でもないのに…", 2002, 135401, "2026/06/15 12:00:00", 1, 13, 10050, 3.727);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("アネモネ", -470.0, 0.0, "2026/09/22 11:59:59", 9, 7, "──リアみたいに、\nもっと愛想良い接客を…\nいえ──なんでもないです", 2002, 135401, "2026/06/15 12:00:00", 2, 13, 10051, 7.213);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("クリア", -470.0, 0.0, "2026/09/22 11:59:59", 2, 1, "いらっしゃいませー♪\n奉仕活動兼、将来のために\nたくさん働いちゃいます♪", 2002, 135301, "2026/06/15 12:00:00", 1, 13, 10052, 1.874);
INSERT INTO `v1_df8170eebb65f4964a9c514f3136caa19ad3d4a3aa4d5b1db2c763960835d42d` VALUES ("クリア", -470.0, 0.0, "2026/09/22 11:59:59", 2, 2, "アルバイトが終わったら\n海に遊びに行きましょう！\nモネちゃんも一緒に♪", 2002, 135301, "2026/06/15 12:00:00", 2, 13, 10053, 0.0);
